function rosterMerge(first, second) {
  const merged = [];
  let i = 0, j = 0;
  while (i < first.length && j < second.length) merged.push(first[i] <= second[j] ? first[i++] : second[j++]);
  while (i < first.length) merged.push(first[i++]);
  while (j < second.length) merged.push(second[j++]);
  return merged;
}
